INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('58850124065402', 'แม็กกี้ ซอสเหยาะจิ้ม 100 มล. (ลัง24)', 'วัตถุดิบอาหาร เครื่องปรุง', 450, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
