INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8859580900642', 'เอ็ม&ดี ขนมเค้กไก่หยองสอดไส้ครีม 28 กรัม (แพ็ค12)', 'วัตถุดิบเบเกอร์รี่', 56, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
