INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8851683005262', 'ไร่ทิพย์ พริกไทยดำเม็ด 100 กรัม (ลัง100)', 'วัตถุดิบอาหาร เครื่องปรุง', 3600, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
