INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('PD6965007729', 'นางกวัก เกลือ 7.- ซอง (มัด12)', 'วัตถุดิบอาหาร เครื่องปรุง', 72, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
