INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8850987128646', 'มาม่าหมูสับ บิ๊กแพค 95 กรัม (กล่อง24)', 'วัตถุดิบอาหาร เครื่องปรุง', 215, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
