INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('24-8858152034389', 'ชื่นใจ ลำไยในน้ำเชื่อม 500 กรัม (ลัง24)', 'วัตถุดิบทำเครื่องดื่ม', 925, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
