INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8850424002102', 'ยูโรคอปป สกาย อาหารเช้าซีเรียล รสน้ำผึ้ง 70 กรัม (แพ็ค3)', 'วัตถุดิบเบเกอร์รี่', 54, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
