INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('20-8859479402622', 'ลองบีช ผงปั่นเฟรปเป้ 400 กรัม มีนม (ลัง20)', 'วัตถุดิบทำเครื่องดื่ม', 2045, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
