INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8850127004434', 'เนสกาแฟ 3 อิน 1 เอสเปรสโซ เขียว 27 ซอง (ลัง24)', 'วัตถุดิบทำเครื่องดื่ม', 2730, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
