INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8859627820308', 'KNP ถ้วยน้ำจิ้มฝาติด 1oz ทรงเหลี่ยม (ลัง40)', 'ถุง โฟมและบรรจุภัณฑ์', 746, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
