INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8850086141508', 'โอวัลติน ผงชง 140 กรัม โอเมก้า3,6,9 (กล่อง12)', 'วัตถุดิบทำเครื่องดื่ม', 384, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
