INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('6-6962047852186', 'กล่องของขวัญหัวใจ (แพ็ค6)', 'ถุง โฟมและบรรจุภัณฑ์', 120, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
