INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('16-8851241354054', 'ไก่ฟ้า ลูกจาก 1000 กรัม (ลัง16)', 'วัตถุดิบเบเกอร์รี่', 1025, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
