INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8850672210014', 'เทนโซพล๊าส พลาสเตอร์ผ้ายืด (กล่อง100)', 'ของใช้ในบ้านและส่วนตัว', 0, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
