INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8851727903257', 'คอนเน่ 20.- รสชีส (แพ็ค3)', 'วัตถุดิบอาหาร เครื่องปรุง', 57, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
