INSERT OR REPLACE INTO products (id, name, category, price, desc, img, tag, status) VALUES ('8851123706513', 'เบบี้มายด์ สวีทตีัพิงค์ 45 กรัม (แพ็ค6)', 'ของใช้ในบ้านและส่วนตัว', 66, 'ชื่อสินค้า : ไร่ทิพย์ ถั่วดำ 500 กรัม
